    resources:[{type:"steam",label:"Steam",url:"https://store.steampowered.com/app/1669980/"},{type:"vndb",label:"VNDB",url:"https://vndb.org/v30818"},{type:"official",label:"官网",url:"https://www.yuzusoft-sour.com/products/parquet/"}]
