const games=[
  {id:1,title:"ATRI -My Dear Moments-",titleJp:"ATRI -My Dear Moments-",year:2020,developer:"Frontwing / 枕",platforms:["PC","Switch","Mobile"],tags:["科幻","治愈","催泪","全年龄"],desc:"海平面上升淹没大部分陆地的小镇里，少年斑鸠夏生与机器人少女亚托莉相遇。在沉没的城镇中寻找希望与未来的感人故事。",background:"不远的未来，海平面急剧上升，许多沿海城市被水淹没。少年斑鸠夏生在祖母去世后，回到海底沉睡的故乡小镇。在祖母留下的潜水艇仓库中，他偶然捞起了一个不可思议的「遗产」——机器人少女亚托莉。\n\n亚托莉自称高性能机器人，却连跑步都会摔倒；自称情感丰富，有时却比人类更感性。随着与亚托莉相处的日常展开，夏生逐渐发现她身上隐藏的秘密，以及祖母留下的「最后的命令」……\n\n这是一个关于失去、希望与「心灵」的故事，在大海之下的怀念中，寻找属于明天的光辉。",characters:[{name:"亚托莉",cv:"赤尾ひかる",desc:"自称高性能的机器人少女，天真烂漫、感情丰富，口头禅「我是高性能的嘛！」"},{name:"斑鸠夏生",cv:"小野賢章",desc:"失去一条腿的少年，因事故失去母亲而封闭内心，遇见亚托莉后逐渐敞开心扉。"},{name:"神白水菜萌",cv:"高橋未奈美",desc:"夏生的青梅竹马，开朗活泼，默默关心着夏生。"},{name:"野岛竜司",cv:"細谷佳正",desc:"潜水店老板，豪爽仗义，常给予夏生帮助和引导。"}],cgCount:42,resources:[{type:"official",label:"官网",url:"https://atri-mdm.com/"},{type:"steam",label:"Steam",url:"https://store.steampowered.com/app/1230140/"},{type:"vndb",label:"VNDB",url:"https://vndb.org/v26808"},]},
  {id:2,title:"樱花、萌放。",titleJp:"さくら、もゆ。-as the Night's, Reincarnation-",year:2020,developer:"Favorite",platforms:["PC"],tags:["魔法少女","催泪","泣きゲー","奇幻"],desc:"拥有特殊能力的魔法少女们的命运交织，在樱花盛开的季节里展开的温情奇迹。Favorite经典催泪之作。",background:"在一个有「魔法少女」存在的世界里，少年少女们的命运交织在一起。故事围绕着拥有特殊能力的少女们，以及她们与周围人之间产生的羁绊展开。\n\n樱花盛开的季节，那是奇迹降临的预兆。每一个女孩都背负着自己的愿望与伤痛，在战斗中寻找属于自己的答案。这是一部关于牺牲、选择与「再见」的物语。\n\nFavorite 品牌集大成之作，以其独特的世界观和泣ける展开，让无数玩家泪洒键盘。",characters:[{name:"柊ハル",cv:"南條愛乃",desc:"开朗的魔法少女，笑容感染每个人，内心藏着孤独。"},{name:"黒猫",cv:"花澤香菜",desc:"神秘的黑猫姿态少女，真实身份是故事的关键。"},{name:"夜月姫織",cv:"種﨑敦美",desc:"优雅大小姐，魔力强大，肩负家族使命。"}],cgCount:85,resources:[{type:"official",label:"官网",url:"https://www.favo-soft.jp/soft/product/sakuramoyu/"},{type:"vndb",label:"VNDB",url:"https://vndb.org/v25306"},{type:"store",label:"Getchu",url:"https://www.getchu.com/soft.phtml?id=1065953"}]},
  {id:3,title:"终之Stella",titleJp:"終のステラ",year:2022,developer:"Key",platforms:["PC","Mobile"],tags:["科幻","末世","公路","全年龄"],desc:"Key社科幻短篇系列第二弹。末日世界中搬运工裘德与仿生人少女菲莉娅的公路旅途物语。脚本田中ロミオ。",background:"人类灭亡后的世界。由于机械生命体「奇异点」的出现，人类文明已走向终结。\n\n主人公裘德是一名「搬运工」，在废墟中护送货物为生。某日，他接到一份特殊的委托——将一位名叫菲莉娅的仿生人少女安全送到目的地。在这条充满危险的旅途中，裘德在菲莉娅身上逐渐看到了「人类」的影子。\n\n这是一个关于什么是「人类」、什么是「心」的公路旅行科幻故事。脚本由田中ロミオ执笔。",characters:[{name:"菲莉娅",cv:"指出毬亜",desc:"被护送的仿生人少女，天真纯朴，对世界充满好奇。"},{name:"裘德·格雷",cv:"木村良平",desc:"在废墟中搬运货物的独行侠，冷硬外表下有温柔的心。"}],cgCount:30,resources:[{type:"official",label:"官网",url:"https://key.visualarts.gr.jp/kinetic/tsui_no_stella/"},{type:"steam",label:"Steam",url:"https://store.steampowered.com/app/1923310/"},{type:"vndb",label:"VNDB",url:"https://vndb.org/v35704"}]},
  {id:4,title:"GINKA",titleJp:"GINKA",year:2023,developer:"Frontwing",platforms:["PC","Switch"],tags:["纯爱","夏日","神隐","全年龄"],desc:"《ATRI》原班人马打造。夏日海岛上，少年与从「神隐」归来的青梅竹马银花的再会与别离。",background:"故事发生在夏季的姬沙罗岛。五年前，女主角银花在夏祭之夜突然「神隐」，从此消失在众人面前。五年后，正在读高中的少年回到岛上参加夏祭，在那里与银花不可思议地再会了。\n\n银花的外貌停留在五年前的模样，而时间却已经过去。两人在夏日海岛上度过的每一天，都在逐渐揭开「神隐」背后的真相。\n\n由《ATRI》制作人紺野アスタ与画师ゆさの再度联手的纯爱物语。",characters:[{name:"银花",cv:"長谷川育美",desc:"五年前在夏祭之夜神隐的青梅竹马，以不变的姿态重新出现，温柔而坚定。"}],cgCount:35,resources:[{type:"official",label:"官网",url:"https://ginka.frontwing.jp/"},{type:"steam",label:"Steam",url:"https://store.steampowered.com/app/2536840/"},{type:"vndb",label:"VNDB",url:"https://vndb.org/v39172"}]},
  {id:5,title:"Anonymous;Code",titleJp:"アノニマス・コード",year:2022,developer:"MAGES. / CHIYOMARU",platforms:["PC","Switch","PS4"],tags:["科幻","悬疑","科学ADV","黑客"],desc:"科学ADV系列新作。天才黑客步论以「存档与读取」能力拯救世界的科幻悬疑巨制。",background:"2037年，东京·中野。主人公高岡步论是一名天才黑客，拥有「存档与读取」的特殊能力——他可以像操作游戏一样对现实进行Save/Load。\n\n面对即将到来的世界危机，步论利用这一能力反复尝试、挑战未来。然而，每一次的「读取」都不是毫无代价的……\n\n科学ADV系列的精神续作，延续了《命运石之门》的世界观，探讨模拟假说与人类自由意志的界限。",characters:[{name:"高岡步论",cv:"千葉翔也",desc:"拥有Save/Load能力的天才黑客少年，轻浮但关键时刻极具行动力。"},{name:"倉科メグル",cv:"夏川椎菜",desc:"步论的搭档少女黑客，冷静理智的最佳吐槽役。"}],cgCount:55,resources:[{type:"official",label:"官网",url:"https://anonymouscode.jp/"},{type:"steam",label:"Steam",url:"https://store.steampowered.com/app/2291020/"},{type:"vndb",label:"VNDB",url:"https://vndb.org/v17952"}]},
  {id:6,title:"素晴日 HD",titleJp:"素晴らしき日々 HD",year:2020,developer:"ケロQ",platforms:["PC"],tags:["电波","哲学","心理","名作"],desc:"电波系名作HD重制。六个视点编织的「美好的每一天」，哲学、宗教、心理学交织的深度杰作。",background:"六个不同视角交织而成的群像剧。故事从水上由岐的视点开始，逐渐扩展至高島ざくろ、間宮卓司、悠木皆守等多位角色的视角。\n\n「天空为何如此之蓝？」\n\n看似日常的校园生活中，隐藏着令人战栗的真相。哲学、宗教、心理学等多重元素交织，使得作品被誉为最具深度与争议性的视觉小说之一。\n\nHD版本对画面进行了全面重制。",characters:[{name:"水上由岐",cv:"かわしまりの",desc:"活泼开朗的少女，爱好网球，似乎有不为人知的另一面。"},{name:"高島ざくろ",cv:"涼屋スイ",desc:"内向寡言的少女，总带着兔子玩偶。"},{name:"間宮卓司",cv:"佐山森",desc:"看似普通的少年，对世界抱有独特看法。"}],cgCount:70,resources:[{type:"vndb",label:"VNDB",url:"https://vndb.org/v3144"},{type:"store",label:"DLsite",url:"https://www.dlsite.com/pro/work/subaku-hd"}]},
  {id:7,title:"白昼夢の青写真",titleJp:"白昼夢の青写真",year:2020,developer:"Laplacian",platforms:["PC"],tags:["群像","穿越","文艺","时代剧"],desc:"跨越三个时代的群像物语。世界的少女与少女的世界，在反复的「白昼梦」中寻找真实自我。",background:"故事由三个不同时代的事件构成：Case1 凪白（现代）、Case2 Olivia（19世纪末）、Case3 風織（昭和时代）。三个看似无关的故事，却由「做梦」这一现象紧密相连。\n\n女主角们都在做着奇妙的梦——她们在梦中变为不同时代的不同人物。而当三个故事交汇之时，真相将逐渐浮出水面。\n\n这是一部关于记忆、身份与爱的宏大叙事，Laplacian 的野心之作。",characters:[{name:"波多野 凪",cv:"神代岬",desc:"现代女高中生，梦中化身为19世纪贵族少女。"},{name:"オリヴィア",cv:"歩サラ",desc:"19世纪末英国少女，怀抱成为演员的梦想。"},{name:"有島 風織",cv:"はちみつぼい",desc:"昭和时代少女，在传统与变革的夹缝中挣扎。"}],cgCount:60,resources:[{type:"official",label:"官网",url:"https://laplacian.jp/hakuchumu/"},{type:"steam",label:"Steam",url:"https://store.steampowered.com/app/2411940/"},{type:"vndb",label:"VNDB",url:"https://vndb.org/v28107"}]},
  {id:8,title:"Fate/Samurai Remnant",titleJp:"Fate/Samurai Remnant",year:2023,developer:"TYPE-MOON / 光荣特库摩",platforms:["PC","Switch","PS4","PS5"],tags:["Fate","江户","动作RPG","圣杯战争"],desc:"江户圣杯战争开幕。少年宫本伊织与Saber共同踏上争夺万能许愿机「盈月」的战斗之旅。",background:"庆安四年，江户。以江户时代为舞台的全新圣杯战争「盈月之仪」开幕。\n\n少年宫本伊织被卷入这场争夺万能许愿机「盈月」的仪式中，与以Saber职阶现界的剑士缔结契约，共同迎战其他六组Master与Servant。\n\n这是一部融合了历史与奇幻的动作RPG型视觉小说，由光荣特库摩与TYPE-MOON强强联手打造。",characters:[{name:"Saber",cv:"山村響",desc:"与伊织结下契约的剑士Servant，性格温和但战斗力极强。"},{name:"宫本伊织",cv:"河西健吾",desc:"宫本武藏的弟子，在平静生活中被卷入盈月之仪。"},{name:"鄭成功",cv:"前野智昭",desc:"明国出身的Master，为国而战的策略家。"}],cgCount:80,resources:[{type:"official",label:"官网",url:"https://www.gamecity.ne.jp/fate-sr/"},{type:"steam",label:"Steam",url:"https://store.steampowered.com/app/2095860/"},{type:"vndb",label:"VNDB",url:"https://vndb.org/v39173"}]},
  {id:9,title:"LOOPERS",titleJp:"LOOPERS",year:2021,developer:"Key",platforms:["PC","Mobile","Switch"],tags:["时间循环","青春","科幻","全年龄"],desc:"Key科幻短篇第一弹。被困在同一天不断循环的少年少女们的青春群像剧。脚本 竜騎士07。",background:"热衷于GPS寻宝游戏的高中生泰勒，某日在深夜的寻宝中被卷入了一股神秘的力量。醒来后，他发现世界陷入了无尽的时间循环——同一天在一遍遍地重复。\n\n在这个循环的世界中，泰勒遇到了同样被困在「今日」中的伙伴们。他们自称「LOOPERS」，在这无尽的日常中寻找着突破困局的方法。\n\n这是Key社「Kinetic Novel」科幻短篇系列的首部作品，脚本由竜騎士07执笔。",characters:[{name:"ミア",cv:"金子彩花",desc:"LOOPERS核心成员，活泼开朗，对时间循环有独特见解。"},{name:"ヒルダ",cv:"井ノ上奈々",desc:"LOOPERS成员，冷静沉着负责分析循环现象。"}],cgCount:25,resources:[{type:"steam",label:"Steam",url:"https://store.steampowered.com/app/1811500/"},{type:"vndb",label:"VNDB",url:"https://vndb.org/v28895"}]},
