// ===== AUDIO ENGINE =====
let audio=new Audio();let currentTrack=-1;let isPlaying=false;
function loadTrack(i){
  if(i<0||i>=playlist.length)return;
  currentTrack=i;
  const t=playlist[i];
  document.getElementById('trackTitle').textContent='🎵 '+t.title;
  document.getElementById('trackSource').textContent='🎮 '+t.game;
  document.querySelectorAll('.playlist-item').forEach((el,j)=>el.classList.toggle('active',j===i));
  audio.src=t.src;audio.volume=document.getElementById('volumeSlider').value/100;
  audio.play().then(()=>{isPlaying=true;updatePlayBtn()}).catch(()=>{isPlaying=false;updatePlayBtn()});
}
function togglePlay(){if(currentTrack<0)loadTrack(0);else if(isPlaying){audio.pause();isPlaying=false}else{audio.play().then(()=>{isPlaying=true}).catch(()=>{isPlaying=false});updatePlayBtn()}updatePlayBtn()}
function updatePlayBtn(){document.getElementById('playBtn').textContent=isPlaying?'⏸':'▶';const mt=document.getElementById('musicToggle');mt.classList.toggle('playing',isPlaying)}
function nextTrack(){loadTrack((currentTrack+1)%playlist.length)}
function prevTrack(){loadTrack((currentTrack-1+playlist.length)%playlist.length)}
function setVolume(v){audio.volume=v/100}
audio.addEventListener('ended',nextTrack);
audio.addEventListener('play',()=>{isPlaying=true;updatePlayBtn()});
audio.addEventListener('pause',()=>{isPlaying=false;updatePlayBtn()});

