// ===== INIT =====
function init(){
  populateDevFilter();
  populateTagFilters();
  renderGames(games);
  renderResourceSites();
}
function populateDevFilter(){
  const devs=[...new Set(games.map(g=>g.developer))].sort();
  const sel=document.getElementById('filterDev');
  devs.forEach(d=>{const o=document.createElement('option');o.value=d;o.textContent=d;sel.appendChild(o)});
}
function populateTagFilters(){
  const allTags=[...new Set(games.flatMap(g=>g.tags||[]))].sort();
  const container=document.getElementById('tagFilters');
  allTags.forEach(t=>{
    const el=document.createElement('span');
    el.className='tag-filter';el.textContent=t;
    el.onclick=function(){this.classList.toggle('active');applyFilters()};
    container.appendChild(el);
  });
}
function renderResourceSites(){
  const c=document.getElementById('resourceSites');
  resourceSites.forEach(s=>{
    const card=document.createElement('a');
    card.className='resource-site-card';card.href=s.url;card.target='_blank';card.rel='noopener';
    card.innerHTML=`<div class="site-icon">${s.icon}</div><h4>${s.name}</h4><div class="site-url">${s.url.replace('https://','')}</div><p>${s.desc}</p>`;
    c.appendChild(card);
  });
}

// ===== RENDER GAMES =====
function renderGames(gameList){
  const grid=document.getElementById('gamesGrid');
  const noRes=document.getElementById('noResults');
  const count=document.getElementById('gameCount');
  grid.innerHTML='';count.textContent=gameList.length;
  if(gameList.length===0){grid.style.display='none';noRes.style.display='block';return}
  grid.style.display='grid';noRes.style.display='none';
  gameList.forEach(game=>{
    const card=document.createElement('div');card.className='game-card';
    card.onclick=()=>openModal(game);
    const coverPath=coverMap[game.id]||'';
    card.innerHTML=`
      <div class="game-card-image">
        <img src="${coverPath}" alt="${game.title}" loading="lazy" onerror="this.style.display='none';this.parentElement.style.background='linear-gradient(135deg,rgba(255,107,157,0.3),rgba(126,200,227,0.3))'">
        <div class="card-overlay"></div>
        <span class="year-badge">${game.year}</span>
      </div>
      <div class="game-card-body">
        <h3>${game.title}</h3>
        <p class="title-jp">${game.titleJp}</p>
        <div class="meta">
          <span class="tag tag-dev">🏢 ${game.developer}</span>
          ${game.platforms.map(p=>`<span class="tag tag-plat">${p}</span>`).join('')}
        </div>
        <p class="desc">${game.desc}</p>
      </div>`;
    grid.appendChild(card);
  });
}

// ===== FILTERS =====
function applyFilters(){
  const search=document.getElementById('searchInput').value.toLowerCase().trim();
  const year=document.getElementById('filterYear').value;
  const plat=document.getElementById('filterPlatform').value;
  const dev=document.getElementById('filterDev').value;
  const activeTags=[...document.querySelectorAll('.tag-filter.active')].map(el=>el.textContent);
  let f=games;
  if(search){f=f.filter(g=>g.title.toLowerCase().includes(search)||g.titleJp.includes(search)||g.developer.toLowerCase().includes(search)||g.desc.toLowerCase().includes(search)||g.characters.some(c=>c.name.includes(search)||c.cv.includes(search)||c.desc.includes(search)||(g.tags||[]).some(t=>t.includes(search))))}
  if(year)f=f.filter(g=>g.year===parseInt(year));
  if(plat)f=f.filter(g=>g.platforms.includes(plat));
  if(dev)f=f.filter(g=>g.developer===dev);
  if(activeTags.length>0)f=f.filter(g=>activeTags.every(t=>(g.tags||[]).includes(t)));
  renderGames(f);
  updateAutocomplete(search);
}
function resetFilters(){
  document.getElementById('searchInput').value='';
  document.getElementById('filterYear').value='';
  document.getElementById('filterPlatform').value='';
  document.getElementById('filterDev').value='';
  document.querySelectorAll('.tag-filter.active').forEach(el=>el.classList.remove('active'));
  document.getElementById('autocompleteDropdown').classList.remove('active');
  renderGames(games);
}

// ===== AUTOCOMPLETE =====
let acSelected=-1;
function updateAutocomplete(query){
  const dd=document.getElementById('autocompleteDropdown');
  if(!query||query.length<1){dd.classList.remove('active');acSelected=-1;return}
  const suggestions=[];
  games.forEach(g=>{
    if(g.title.toLowerCase().includes(query))suggestions.push({type:'游戏',text:g.title});
    if(g.developer.toLowerCase().includes(query))suggestions.push({type:'开发商',text:g.developer});
    g.characters.forEach(c=>{if(c.name.includes(query)||c.cv.includes(query))suggestions.push({type:'角色',text:c.name+' ('+c.cv+')'})});
    (g.tags||[]).forEach(t=>{if(t.includes(query))suggestions.push({type:'标签',text:t})});
  });
  const unique=[...new Map(suggestions.map(s=>[s.type+s.text,s])).values()].slice(0,8);
  if(unique.length===0){dd.classList.remove('active');return}
  dd.innerHTML=unique.map((s,i)=>`<div class="autocomplete-item${i===acSelected?' selected':''}" data-index="${i}"><span class="ac-type">${s.type}</span><span class="ac-text">${s.text}</span></div>`).join('');
  dd.classList.add('active');
  dd.querySelectorAll('.autocomplete-item').forEach(el=>el.onclick=function(){
    document.getElementById('searchInput').value=this.querySelector('.ac-text').textContent;
    dd.classList.remove('active');applyFilters();
  });
}
document.getElementById('searchInput').addEventListener('input',e=>{acSelected=-1;applyFilters()});
document.getElementById('searchInput').addEventListener('keydown',e=>{
  const dd=document.getElementById('autocompleteDropdown');
  const items=dd.querySelectorAll('.autocomplete-item');
  if(e.key==='ArrowDown'){e.preventDefault();acSelected=Math.min(acSelected+1,items.length-1);items.forEach((el,i)=>el.classList.toggle('selected',i===acSelected))}
  else if(e.key==='ArrowUp'){e.preventDefault();acSelected=Math.max(acSelected-1,-1);items.forEach((el,i)=>el.classList.toggle('selected',i===acSelected))}
  else if(e.key==='Enter'&&acSelected>=0){e.preventDefault();items[acSelected].click()}
  else if(e.key==='Escape'){dd.classList.remove('active');acSelected=-1}
});
document.addEventListener('click',e=>{if(!e.target.closest('.search-input-wrap'))document.getElementById('autocompleteDropdown').classList.remove('active')});

// Listeners
document.getElementById('filterYear').addEventListener('change',applyFilters);
document.getElementById('filterPlatform').addEventListener('change',applyFilters);
document.getElementById('filterDev').addEventListener('change',applyFilters);

// ===== MODAL =====
function openModal(game){
  document.getElementById('modalTitle').textContent=game.title;
  document.getElementById('modalTitleJp').textContent=game.titleJp;
  const header=document.querySelector('.modal-header');
  const coverPath=coverMap[game.id];
  if(coverPath)header.style.backgroundImage=`url(${coverPath})`;
  else header.style.backgroundImage='';
  document.getElementById('modalBody').innerHTML=buildModal(game);
  document.getElementById('modalOverlay').classList.add('active');
  document.body.style.overflow='hidden';
}
function closeModal(){
  document.getElementById('modalOverlay').classList.remove('active');
  document.body.style.overflow='';
}
function closeModalOutside(e){if(e.target===document.getElementById('modalOverlay'))closeModal()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});

function buildModal(game){
  let h=`<div class="meta-info"><span class="meta-item">📅 <strong>发售:</strong> ${game.year}年</span><span class="meta-item">🏢 <strong>开发商:</strong> ${game.developer}</span><span class="meta-item">💻 <strong>平台:</strong> ${game.platforms.join(' / ')}</span><span class="meta-item">🖼️ <strong>CG:</strong> ${game.cgCount}+</span></div>`;
  if(game.tags)h+=`<div class="meta-info">${game.tags.map(t=>`<span class="meta-item" style="background:rgba(126,200,227,0.1);border-color:rgba(126,200,227,0.2)">🏷️ ${t}</span>`).join('')}</div>`;
  h+=`<section><h3>📖 背景说明</h3><p style="white-space:pre-line;line-height:1.9;">${game.background}</p></section>`;
  h+='<section><h3>👥 人物简介</h3><div class="char-grid">';
  game.characters.forEach(c=>{h+=`<div class="char-card"><div class="char-avatar">🎭</div><div class="char-info"><h4>${c.name}</h4><p class="cv">🎙️ CV: ${c.cv}</p><p>${c.desc}</p></div></div>`});
  h+='</div></section>';

  // CG Gallery with sample images
  const coverPath=coverMap[game.id];
  h+=`<section><h3>🖼️ 官方CG (共${game.cgCount}张)</h3><div class="cg-gallery">`;
  // Show cover as first CG
  if(coverPath)h+=`<div class="cg-item"><img src="${coverPath}" alt="封面" loading="lazy"><span class="cg-label">封面</span></div>`;
  // Sample CG placeholders
  for(let i=0;i<Math.min(5,game.cgCount-1);i++){
    const cgId=game.id*100+i+1;
    h+=`<div class="cg-item"><div style="width:100%;height:100%;background:linear-gradient(135deg,rgba(196,113,245,0.2),rgba(126,200,227,0.2));display:flex;align-items:center;justify-content:center;font-size:2.5rem">🎨</div><span class="cg-label">CG #${i+1}</span></div>`;
  }
  if(game.cgCount>6)h+=`<div class="cg-item"><div style="width:100%;height:100%;background:rgba(196,113,245,0.15);display:flex;align-items:center;justify-content:center;font-size:1.2rem;color:rgba(200,180,220,0.7)">+${game.cgCount-6}<br>更多</div></div>`;
  h+='</div>';
  h+=`<p style="font-size:0.8rem;color:rgba(200,180,220,0.5);margin-top:8px">💡 更多CG请访问 2DFan / VNDB / 月幕Galgame 查看完整画廊</p></section>`;

  h+='<section><h3>🔗 资源获取途径</h3><div class="resource-links">';
  const tMap={official:'res-official',steam:'res-steam',vndb:'res-vndb',store:'res-store',resource:'res-resource'};
  game.resources.forEach(r=>{h+=`<a href="${r.url}" target="_blank" rel="noopener" class="resource-link ${tMap[r.type]||'res-store'}">${r.label}</a>`});
  h+=`<div style="margin-top:14px;padding:14px;background:rgba(255,211,0,0.06);border:1px solid rgba(255,211,0,0.15);border-radius:var(--radius-sm);font-size:0.85rem;color:rgba(255,211,0,0.75)">
    💡 <strong>阿罗娜的小提示：</strong>正版首选 Steam / 官网！中文资源可参考 Hikarinagi / NekoGAL / 稻荷GAL / Singureo / 2DFan。CG完整包请在 2DFan 或 月幕Galgame 搜索～
  </div></section>`;
  return h;
}

init();
