<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>🌸 Galgame 年鉴 · 阿罗娜的恋爱指南</title>
<style>
:root{--pink:#ff6b9d;--purple:#c471f5;--blue:#7ec8e3;--bg:rgba(10,8,24,0.92);--text:#e0d8f0;--radius:16px}
*{margin:0;padding:0;box-sizing:border-box}
body{
  font-family:'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif;
  color:#e0d8f0;line-height:1.6;min-height:100vh;overflow-x:hidden;
  background:#0a0818;
  background-image:url('galgame_assets/bg/summer_pockets_bg.jpg');
  background-size:cover;background-position:center;background-attachment:fixed;
  position:relative;
}
body::before{
  content:'';position:fixed;inset:0;z-index:0;
  background:linear-gradient(180deg,rgba(10,8,24,0.65) 0%,rgba(10,8,24,0.8) 40%,rgba(10,8,24,0.92) 100%);
}
body::after{
  content:'';position:fixed;inset:0;z-index:0;
  background:radial-gradient(ellipse at 30% 20%,rgba(255,107,157,0.08) 0%,transparent 50%),
             radial-gradient(ellipse at 70% 60%,rgba(126,200,227,0.08) 0%,transparent 50%),
             radial-gradient(ellipse at 50% 80%,rgba(196,113,245,0.06) 0%,transparent 50%);
}

/* Sakura petals */
.petal-container{position:fixed;inset:0;pointer-events:none;z-index:9999}
.petal{position:absolute;top:-5%;font-size:1.2rem;animation:fall linear forwards;pointer-events:none;opacity:0.6}
@keyframes fall{0%{transform:translateY(0) rotate(0deg) translateX(0);opacity:0.8}50%{transform:translateY(50vh) rotate(180deg) translateX(80px);opacity:0.5}100%{transform:translateY(110vh) rotate(360deg) translateX(-40px);opacity:0}}

/* Mini Murasame click */
.mini-murasame{position:fixed;pointer-events:none;z-index:10002;animation:muraPop 1.4s ease-out forwards;text-align:center}
.mini-murasame .mura-body{font-size:42px;line-height:1;filter:drop-shadow(0 2px 4px rgba(255,180,100,0.4))}
.mini-murasame .mura-text{font-size:11px;color:#ffe0c0;margin-top:2px;text-shadow:0 0 6px rgba(255,180,100,0.5)}
@keyframes muraPop{
  0%{transform:translateY(0) scale(0) rotate(-30deg);opacity:1}
  20%{transform:translateY(-35px) scale(1.3) rotate(5deg);opacity:1}
  40%{transform:translateY(-45px) scale(1) rotate(0deg);opacity:1}
  100%{transform:translateY(-90px) scale(0.2) rotate(20deg);opacity:0}
}

/* Header */
header{
  position:sticky;top:0;z-index:100;
  background:linear-gradient(180deg,rgba(20,10,40,0.95),rgba(20,10,40,0.85));
  backdrop-filter:blur(16px);padding:24px 20px;text-align:center;
  border-bottom:1px solid rgba(255,107,157,0.15);
  box-shadow:0 4px 30px rgba(0,0,0,0.4);
}
header h1{background:linear-gradient(135deg,#ff6b9d,#c471f5,#7ec8e3);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;font-size:2rem;letter-spacing:2px;font-weight:900}
header .subtitle{color:rgba(200,180,220,0.8);font-size:0.9rem;margin-top:4px}
.header-char{display:inline-block;animation:bounce 2s infinite;font-size:1.4rem}
@keyframes bounce{0%,100%{transform:translateY(0)}30%{transform:translateY(-8px) rotate(5deg)}60%{transform:translateY(0) rotate(-3deg)}}

.container{max-width:1340px;margin:0 auto;padding:0 20px;position:relative;z-index:1}

/* Search */
.search-section{
  background:rgba(20,12,38,0.9);backdrop-filter:blur(12px);
  border:1px solid rgba(255,107,157,0.15);border-radius:var(--radius);
  padding:24px;margin:-16px auto 24px;max-width:1340px;
  box-shadow:0 8px 32px rgba(0,0,0,0.3);position:relative;z-index:50;
}
.search-row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}
.search-input-wrap{flex:1;min-width:200px;position:relative}
.search-input{width:100%;padding:12px 18px;border:2px solid rgba(255,107,157,0.25);border-radius:30px;font-size:0.95rem;outline:none;transition:all 0.3s;background:rgba(15,8,30,0.8);color:#e0d8f0}
.search-input::placeholder{color:rgba(200,180,220,0.45)}
.search-input:focus{border-color:#ff6b9d;box-shadow:0 0 20px rgba(255,107,157,0.15)}
.autocomplete-dropdown{display:none;position:absolute;top:100%;left:0;right:0;background:rgba(20,10,35,0.98);border:1px solid rgba(255,107,157,0.25);border-radius:0 0 14px 14px;max-height:220px;overflow-y:auto;z-index:60;margin-top:3px}
.autocomplete-dropdown.active{display:block}
.autocomplete-item{padding:10px 16px;cursor:pointer;display:flex;align-items:center;gap:8px;border-bottom:1px solid rgba(255,255,255,0.04);transition:background 0.2s}
.autocomplete-item:hover,.autocomplete-item.selected{background:rgba(255,107,157,0.15)}
.autocomplete-item .ac-type{font-size:0.65rem;padding:2px 8px;border-radius:10px;background:rgba(255,107,157,0.2);color:#ff6b9d;white-space:nowrap}
.autocomplete-item .ac-text{color:#e0d8f0;font-size:0.85rem}

.filter-select{padding:11px 14px;border:2px solid rgba(255,107,157,0.25);border-radius:30px;font-size:0.9rem;background:rgba(15,8,30,0.8);cursor:pointer;outline:none;min-width:120px;color:#e0d8f0}
.filter-select:focus{border-color:#c471f5}
.btn{padding:11px 22px;border:none;border-radius:30px;font-size:0.9rem;cursor:pointer;transition:all 0.3s;font-weight:700}
.btn-primary{background:linear-gradient(135deg,#ff6b9d,#c471f5);color:#fff;box-shadow:0 4px 14px rgba(196,113,245,0.3)}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 6px 22px rgba(196,113,245,0.5)}
.btn-reset{background:rgba(255,255,255,0.05);color:#b8a8d0;border:1px solid rgba(255,255,255,0.08)}
.btn-reset:hover{border-color:#c471f5;color:#d4c4f0}
.result-count{margin-top:10px;font-size:0.85rem;color:rgba(200,180,220,0.6)}
.result-count span{color:#ff6b9d;font-weight:700}
.tag-filters{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
.tag-filter{padding:5px 12px;border-radius:16px;font-size:0.72rem;font-weight:600;cursor:pointer;transition:all 0.25s;border:1px solid transparent;background:rgba(255,107,157,0.06);color:rgba(200,180,220,0.6);border-color:rgba(255,107,157,0.08)}
.tag-filter:hover,.tag-filter.active{background:rgba(255,107,157,0.18);color:#ff6b9d;border-color:rgba(255,107,157,0.3)}

/* Game cards */
.games-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:20px;padding-bottom:40px}
.game-card{
  background:rgba(25,15,40,0.85);backdrop-filter:blur(6px);border-radius:var(--radius);
  overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,0.3);cursor:pointer;
  transition:all 0.35s cubic-bezier(0.4,0,0.2,1);
  border:1px solid rgba(255,107,157,0.08);position:relative;
}
.game-card::before{content:'';position:absolute;inset:-2px;border-radius:18px;background:linear-gradient(135deg,transparent,rgba(255,107,157,0.25),rgba(126,200,227,0.25),transparent);opacity:0;transition:opacity 0.35s;z-index:-1;filter:blur(4px)}
.game-card:hover::before{opacity:1}
.game-card:hover{transform:translateY(-6px) scale(1.02);box-shadow:0 14px 36px rgba(196,113,245,0.2);border-color:rgba(255,107,157,0.3)}
.game-card-image{height:220px;position:relative;overflow:hidden;background:#1a1030}
.game-card-image img{width:100%;height:100%;object-fit:cover;transition:transform 0.5s}
.game-card:hover .game-card-image img{transform:scale(1.06)}
.game-card-image .year-badge{position:absolute;top:12px;right:12px;background:rgba(0,0,0,0.55);backdrop-filter:blur(6px);color:#fff;padding:4px 12px;border-radius:18px;font-size:0.75rem;font-weight:700;border:1px solid rgba(255,255,255,0.15);z-index:2}
.game-card-image .card-overlay{position:absolute;bottom:0;left:0;right:0;height:55%;background:linear-gradient(transparent,rgba(0,0,0,0.7))}
.game-card-body{padding:16px}
.game-card-body h3{font-size:1.05rem;color:#f0e8ff;margin-bottom:2px}
.game-card-body .title-jp{font-size:0.7rem;color:rgba(200,180,220,0.55);margin-bottom:8px}
.game-card-body .meta{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:8px}
.tag{padding:3px 10px;border-radius:12px;font-size:0.68rem;font-weight:600}
.tag-dev{background:rgba(126,200,227,0.18);color:#7ec8e3;border:1px solid rgba(126,200,227,0.15)}
.tag-plat{background:rgba(255,211,0,0.12);color:#ffd54f;border:1px solid rgba(255,211,0,0.15)}
.game-card-body .desc{font-size:0.8rem;color:rgba(200,180,220,0.6);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}

/* Modal */
.modal-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:200;justify-content:center;align-items:flex-start;padding:20px;overflow-y:auto;backdrop-filter:blur(4px)}
.modal-overlay.active{display:flex}
.modal{background:rgba(20,12,35,0.97);backdrop-filter:blur(16px);border-radius:var(--radius);max-width:880px;width:100%;margin:20px 0;box-shadow:0 20px 60px rgba(0,0,0,0.5),0 0 40px rgba(196,113,245,0.1);animation:slideUp 0.35s cubic-bezier(0.34,1.56,0.64,1);border:1px solid rgba(196,113,245,0.15)}
@keyframes slideUp{from{opacity:0;transform:translateY(40px) scale(0.96)}to{opacity:1;transform:translateY(0) scale(1)}}
.modal-header{padding:22px 26px;display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid rgba(255,107,157,0.12);position:relative;background-size:cover;background-position:center}
.modal-header::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(20,12,35,0.82),rgba(15,8,28,0.9));border-radius:var(--radius) var(--radius) 0 0}
.modal-header>*{position:relative;z-index:1}
.modal-header h2{font-size:1.5rem;color:#f0e8ff}
.modal-header .title-jp{font-size:0.8rem;color:rgba(200,180,220,0.55)}
.modal-close{position:relative;z-index:2;background:none;border:1px solid rgba(255,255,255,0.12);font-size:1.6rem;cursor:pointer;color:rgba(200,180,220,0.6);padding:3px 10px;border-radius:50%;transition:all 0.3s}
.modal-close:hover{color:#ff6b9d;border-color:#ff6b9d;background:rgba(255,107,157,0.1)}
.modal-body{padding:22px 26px}
.modal-body section{margin-bottom:20px}
.modal-body section h3{font-size:1.1rem;background:linear-gradient(135deg,#ff6b9d,#c471f5);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;margin-bottom:10px;padding-bottom:6px;border-bottom:2px solid rgba(255,107,157,0.15)}
.meta-info{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:14px}
.meta-item{padding:5px 14px;border-radius:18px;font-size:0.8rem;background:rgba(255,107,157,0.06);border:1px solid rgba(255,107,157,0.1)}
.meta-item strong{color:#ff6b9d}
.char-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px}
.char-card{display:flex;gap:12px;background:rgba(30,15,50,0.5);padding:12px;border-radius:10px;transition:all 0.3s;border:1px solid rgba(255,107,157,0.06)}
.char-card:hover{background:rgba(196,113,245,0.08);border-color:rgba(196,113,245,0.2);transform:translateY(-2px)}
.char-avatar{width:64px;height:64px;border-radius:50%;background:linear-gradient(135deg,#c471f5,#ff6b9d);display:flex;align-items:center;justify-content:center;font-size:1.6rem;flex-shrink:0;border:2px solid rgba(255,107,157,0.2)}
.char-info h4{font-size:0.9rem;color:#f0e8ff;margin-bottom:1px}
.char-info .cv{font-size:0.7rem;color:rgba(200,180,220,0.5);margin-bottom:3px}
.char-info p{font-size:0.78rem;color:rgba(200,180,220,0.7);line-height:1.4}
.cg-gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px}
.cg-item{border-radius:10px;overflow:hidden;transition:all 0.3s;cursor:pointer;border:2px solid rgba(126,200,227,0.12);aspect-ratio:16/10}
.cg-item img{width:100%;height:100%;object-fit:cover}
.cg-item:hover{transform:scale(1.06);border-color:rgba(196,113,245,0.5);box-shadow:0 4px 14px rgba(196,113,245,0.2)}
.resource-links{display:flex;flex-wrap:wrap;gap:8px}
.resource-link{display:inline-flex;align-items:center;gap:5px;padding:9px 16px;border-radius:24px;text-decoration:none;font-size:0.85rem;font-weight:600;transition:all 0.3s}
.res-official{background:linear-gradient(135deg,#ff6b9d,#f06292);color:#fff}
.res-official:hover{transform:translateY(-2px);box-shadow:0 4px 14px rgba(255,107,157,0.35)}
.res-vndb{background:rgba(126,200,227,0.18);color:#7ec8e3;border:1px solid rgba(126,200,227,0.2)}
.res-vndb:hover{background:rgba(126,200,227,0.28);transform:translateY(-2px)}
.res-steam{background:#1b2838;color:#fff;border:1px solid #2a475e}
.res-steam:hover{background:#2a475e;transform:translateY(-2px)}
.res-store{background:rgba(255,211,0,0.12);color:#ffd54f;border:1px solid rgba(255,211,0,0.2)}
.res-store:hover{background:rgba(255,211,0,0.22);transform:translateY(-2px)}
.res-resource{background:rgba(196,113,245,0.12);color:#c471f5}
.res-resource:hover{background:rgba(196,113,245,0.22);transform:translateY(-2px)}

/* Music Player */
.music-player{position:fixed;bottom:60px;left:50%;transform:translateX(-50%);z-index:310;display:flex;align-items:center;gap:8px;background:rgba(20,10,35,0.95);backdrop-filter:blur(12px);border:1px solid rgba(255,107,157,0.2);border-radius:40px;padding:8px 16px;box-shadow:0 4px 20px rgba(0,0,0,0.4);transition:all 0.3s}
.music-player.collapsed{padding:0;background:transparent;border:none;box-shadow:none;bottom:16px}
.music-info{display:flex;align-items:center;gap:8px;max-width:200px}
.music-info .track-text{font-size:0.78rem;color:#e0d8f0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.music-btn{width:34px;height:34px;border-radius:50%;border:1px solid rgba(255,255,255,0.12);background:rgba(255,255,255,0.04);color:#c8b8e0;cursor:pointer;font-size:0.9rem;transition:all 0.3s;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.music-btn:hover{background:rgba(196,113,245,0.2);border-color:#c471f5;color:#f0e8ff}
.music-btn.play-btn{width:40px;height:40px;background:linear-gradient(135deg,#ff6b9d,#c471f5);border:none;color:#fff;font-size:1.1rem}
.music-btn.play-btn.playing{animation:musicPulse 2s infinite}
@keyframes musicPulse{0%,100%{box-shadow:0 0 8px rgba(255,107,157,0.4)}50%{box-shadow:0 0 20px rgba(255,107,157,0.7)}}
.music-volume{width:60px;accent-color:#ff6b9d;flex-shrink:0}
.track-selector{display:flex;gap:4px}
.track-dot{width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,0.2);cursor:pointer;transition:all 0.3s}
.track-dot:hover,.track-dot.active{background:#ff6b9d;box-shadow:0 0 8px rgba(255,107,157,0.5)}

/* Quick nav */
.quick-nav{position:fixed;bottom:16px;right:20px;z-index:150;display:flex;flex-direction:column;gap:8px}
.quick-nav-btn{width:44px;height:44px;border-radius:50%;border:1px solid rgba(196,113,245,0.2);background:rgba(20,12,35,0.9);backdrop-filter:blur(6px);color:#c8b8e0;font-size:1.1rem;cursor:pointer;transition:all 0.3s;display:flex;align-items:center;justify-content:center}
.quick-nav-btn:hover{background:rgba(196,113,245,0.2);border-color:#c471f5;transform:scale(1.1)}

footer{text-align:center;padding:24px 20px 80px;color:rgba(200,180,220,0.4);font-size:0.8rem;position:relative;z-index:1}
footer .heart{color:#ff6b9d}

@media(max-width:768px){
  .games-grid{grid-template-columns:1fr}
  .char-grid{grid-template-columns:1fr}
  .cg-gallery{grid-template-columns:repeat(2,1fr)}
  .music-player{left:16px;right:16px;transform:none;border-radius:36px}
}
.no-results{text-align:center;padding:60px 20px;color:rgba(200,180,220,0.4)}
.no-results .icon{font-size:4rem;margin-bottom:10px}
</style>
</head>
<body>

<div class="petal-container" id="petalContainer"></div>

<header>
  <h1><span class="header-char">🌸</span> Galgame 年鉴 2020-2025</h1>
  <p class="subtitle">✨ 收录35+部精品 · 青桔风编排 · 阿罗娜精心整理 ✨</p>
</header>

<div class="container">
<div class="search-section">
  <div class="search-row">
    <div class="search-input-wrap">
      <input type="text" class="search-input" id="searchInput" placeholder="🔍 搜索游戏名/开发商/角色/CV/标签…" autocomplete="off">
      <div class="autocomplete-dropdown" id="autocompleteDropdown"></div>
    </div>
    <select class="filter-select" id="filterYear"><option value="">📅 全部年份</option></select>
    <select class="filter-select" id="filterPlatform"><option value="">💻 全部平台</option><option value="PC">PC</option><option value="Switch">Switch</option><option value="PS4">PS4</option><option value="PS5">PS5</option><option value="Mobile">手机</option></select>
    <select class="filter-select" id="filterDev"><option value="">🏢 全部开发商</option></select>
    <button class="btn btn-primary" onclick="applyFilters()">🔍</button>
    <button class="btn btn-reset" onclick="resetFilters()">🔄</button>
  </div>
  <div class="tag-filters" id="tagFilters"></div>
  <p class="result-count">共收录 <span id="gameCount">0</span> 部作品</p>
</div>
<div class="games-grid" id="gamesGrid"></div>
<div class="no-results" id="noResults" style="display:none"><div class="icon">😿</div><p>没有找到呢～换个关键词试试？</p></div>
</div>

<!-- Modal -->
<div class="modal-overlay" id="modalOverlay" onclick="closeModalOutside(event)">
  <div class="modal" id="modal">
    <div class="modal-header"><div><h2 id="modalTitle"></h2><span class="title-jp" id="modalTitleJp"></span></div><button class="modal-close" onclick="closeModal()">✕</button></div>
    <div class="modal-body" id="modalBody"></div>
  </div>
</div>

<!-- Music Player -->
<div class="music-player" id="musicPlayer">
  <div class="music-info"><span class="track-text" id="trackText">🎵 点击播放音乐</span></div>
  <div class="track-selector" id="trackDots"></div>
  <button class="music-btn" onclick="prevTrack()">⏮</button>
  <button class="music-btn play-btn" id="playBtn" onclick="togglePlay()">▶</button>
  <button class="music-btn" onclick="nextTrack()">⏭</button>
  <input type="range" class="music-volume" id="volSlider" min="0" max="100" value="35" oninput="setVol(this.value)">
</div>

<div class="quick-nav">
  <button class="quick-nav-btn" onclick="window.scrollTo({top:0,behavior:'smooth'})">⬆</button>
  <button class="quick-nav-btn" onclick="document.getElementById('searchInput').focus()">🔍</button>
  <button class="quick-nav-btn" id="petalToggle" onclick="togglePetals()">🌸</button>
</div>

<footer>
  <p>Made with <span class="heart">❤️</span> by 阿罗娜 · 仅供试运行 · 请支持正版</p>
  <p>封面来源 VNDB · 参考 青桔网/Qingju · 2DFan · Hikarinagi · NekoGAL · 稻荷GAL · 月幕 · Singureo</p>
</footer>

<iframe id="ytPlayer" style="display:none" allow="autoplay"></iframe>

<script>
// ===== SAKURA PETALS =====
const petals=['🌸','💮','🌺','✿','❀'];let petalsActive=true;
function spawnPetal(){if(!petalsActive)return;const p=document.createElement('div');p.className='petal';p.textContent=petals[Math.floor(Math.random()*petals.length)];p.style.left=Math.random()*98+'%';p.style.fontSize=(0.8+Math.random()*1.4)+'rem';p.style.animationDuration=(8+Math.random()*10)+'s';document.getElementById('petalContainer').appendChild(p);setTimeout(()=>p.remove(),16000)}
setInterval(spawnPetal,1600);for(let i=0;i<8;i++)setTimeout(spawnPetal,i*300);
function togglePetals(){petalsActive=!petalsActive;document.getElementById('petalToggle').textContent=petalsActive?'🌸':'🍂';if(!petalsActive)document.getElementById('petalContainer').innerHTML=''}

// ===== MINI MURASAME CLICK =====
document.addEventListener('click',e=>{
  if(e.target.closest('button')||e.target.closest('input')||e.target.closest('select')||e.target.closest('a'))return;
  const m=document.createElement('div');m.className='mini-murasame';
  m.style.left=(e.clientX-24)+'px';m.style.top=(e.clientY-20)+'px';
  m.innerHTML='<div class="mura-body">🦊</div><div class="mura-text">むらさめ～</div>';
  document.body.appendChild(m);setTimeout(()=>m.remove(),1500);
});

// ===== MUSIC PLAYER =====
const tracks=[
