let curTrack=-1,playing=false;
function loadTrack(i){
  curTrack=i;document.getElementById('trackText').textContent='🎵 '+tracks[i].title;
  document.querySelectorAll('.track-dot').forEach((d,j)=>d.classList.toggle('active',j===i));
}
function togglePlay(){
  if(curTrack<0){loadTrack(0)}
  const yt=document.getElementById('ytPlayer');
  if(!playing){
    yt.src=`https://www.youtube.com/embed/${tracks[curTrack].vid}?autoplay=1&loop=1&playlist=${tracks[curTrack].vid}`;
    playing=true;
  }else{yt.src='';playing=false}
  document.getElementById('playBtn').classList.toggle('playing',playing);
  document.getElementById('playBtn').textContent=playing?'⏸':'▶';
}
function nextTrack(){loadTrack((curTrack+1)%tracks.length);if(playing)togglePlay();togglePlay()}
function prevTrack(){loadTrack((curTrack-1+tracks.length)%tracks.length);if(playing)togglePlay();togglePlay()}
function setVol(v){/* YT volume not controllable via iframe without API */}

// Init track dots
tracks.forEach((_,i)=>{
  const d=document.createElement('div');d.className='track-dot';
  d.onclick=()=>{if(curTrack===i){togglePlay()}else{loadTrack(i);if(playing)togglePlay();togglePlay()}};
  document.getElementById('trackDots').appendChild(d);
});

