// ===== INIT =====
function init(){
  populateYears();populateDevFilter();populateTagFilters();
  renderGames(games);
}
function populateYears(){
  const yrs=[...new Set(games.map(g=>g.year))].sort();
  const sel=document.getElementById('filterYear');
  yrs.forEach(y=>{const o=document.createElement('option');o.value=y;o.textContent=y;sel.appendChild(o)});
}
function populateDevFilter(){
  const devs=[...new Set(games.map(g=>g.developer))].sort();
  const sel=document.getElementById('filterDev');
  devs.forEach(d=>{const o=document.createElement('option');o.value=d;o.textContent=d;sel.appendChild(o)});
}
function populateTagFilters(){
  const allTags=[...new Set(games.flatMap(g=>g.tags||[]))].sort();
  const c=document.getElementById('tagFilters');
  allTags.forEach(t=>{const e=document.createElement('span');e.className='tag-filter';e.textContent=t;e.onclick=function(){this.classList.toggle('active');applyFilters()};c.appendChild(e)});
}

function renderGames(list){
  const grid=document.getElementById('gamesGrid'),nr=document.getElementById('noResults'),cnt=document.getElementById('gameCount');
  grid.innerHTML='';cnt.textContent=list.length;
  if(!list.length){grid.style.display='none';nr.style.display='block';return}
  grid.style.display='grid';nr.style.display='none';
  list.forEach(g=>{
    const card=document.createElement('div');card.className='game-card';card.onclick=()=>openModal(g);
    const cover=coverMap[g.id]||'';
    card.innerHTML=`<div class="game-card-image"><img src="${cover}" alt="${g.title}" loading="lazy" onerror="this.style.display='none';this.parentElement.style.background='linear-gradient(135deg,rgba(255,107,157,0.3),rgba(126,200,227,0.3))'"><div class="card-overlay"></div><span class="year-badge">${g.year}</span></div><div class="game-card-body"><h3>${g.title}</h3><p class="title-jp">${g.titleJp}</p><div class="meta"><span class="tag tag-dev">🏢 ${g.developer}</span>${g.platforms.map(p=>`<span class="tag tag-plat">${p}</span>`).join('')}</div><p class="desc">${g.desc}</p></div>`;
    grid.appendChild(card);
  });
}

// ===== FILTERS =====
function applyFilters(){
  const s=document.getElementById('searchInput').value.toLowerCase().trim();
  const y=document.getElementById('filterYear').value,p=document.getElementById('filterPlatform').value,d=document.getElementById('filterDev').value;
  const atags=[...document.querySelectorAll('.tag-filter.active')].map(e=>e.textContent);
  let f=games;
  if(s)f=f.filter(g=>g.title.toLowerCase().includes(s)||g.titleJp.includes(s)||g.developer.toLowerCase().includes(s)||g.desc.toLowerCase().includes(s)||g.characters.some(c=>c.name.includes(s)||c.cv.includes(s))||(g.tags||[]).some(t=>t.includes(s)));
  if(y)f=f.filter(g=>g.year===parseInt(y));
  if(p)f=f.filter(g=>g.platforms.includes(p));
  if(d)f=f.filter(g=>g.developer===d);
  if(atags.length)f=f.filter(g=>atags.every(t=>(g.tags||[]).includes(t)));
  renderGames(f);
  updateAutocomplete(s);
}
function resetFilters(){
  document.getElementById('searchInput').value='';
  document.getElementById('filterYear').value='';document.getElementById('filterPlatform').value='';document.getElementById('filterDev').value='';
  document.querySelectorAll('.tag-filter.active').forEach(e=>e.classList.remove('active'));
  document.getElementById('autocompleteDropdown').classList.remove('active');
  renderGames(games);
}

// ===== AUTOCOMPLETE =====
let acSel=-1;
function updateAutocomplete(q){
  const dd=document.getElementById('autocompleteDropdown');
  if(!q||q.length<1){dd.classList.remove('active');acSel=-1;return}
  const sug=[];games.forEach(g=>{if(g.title.toLowerCase().includes(q))sug.push({t:'游戏',v:g.title});if(g.developer.toLowerCase().includes(q))sug.push({t:'开发商',v:g.developer});g.characters.forEach(c=>{if(c.name.includes(q))sug.push({t:'角色',v:c.name})})});
  const uniq=[...new Map(sug.map(s=>[s.t+s.v,s])).values()].slice(0,8);
  if(!uniq.length){dd.classList.remove('active');return}
  dd.innerHTML=uniq.map((s,i)=>`<div class="autocomplete-item${i===acSel?' selected':''}" data-idx="${i}"><span class="ac-type">${s.t}</span><span class="ac-text">${s.v}</span></div>`).join('');
  dd.classList.add('active');
  dd.querySelectorAll('.autocomplete-item').forEach(el=>el.onclick=function(){document.getElementById('searchInput').value=this.querySelector('.ac-text').textContent;dd.classList.remove('active');applyFilters()});
}
document.getElementById('searchInput').addEventListener('input',e=>{acSel=-1;applyFilters()});
document.getElementById('searchInput').addEventListener('keydown',e=>{
  const dd=document.getElementById('autocompleteDropdown'),items=dd.querySelectorAll('.autocomplete-item');
  if(e.key==='ArrowDown'){e.preventDefault();acSel=Math.min(acSel+1,items.length-1);items.forEach((el,i)=>el.classList.toggle('selected',i===acSel))}
  else if(e.key==='ArrowUp'){e.preventDefault();acSel=Math.max(acSel-1,-1);items.forEach((el,i)=>el.classList.toggle('selected',i===acSel))}
  else if(e.key==='Enter'&&acSel>=0){e.preventDefault();items[acSel].click()}
  else if(e.key==='Escape'){dd.classList.remove('active');acSel=-1}
});
document.addEventListener('click',e=>{if(!e.target.closest('.search-input-wrap'))document.getElementById('autocompleteDropdown').classList.remove('active')});
['filterYear','filterPlatform','filterDev'].forEach(id=>document.getElementById(id).addEventListener('change',applyFilters));

// ===== MODAL =====
function openModal(g){
  document.getElementById('modalTitle').textContent=g.title;
  document.getElementById('modalTitleJp').textContent=g.titleJp;
  const hdr=document.querySelector('.modal-header'),cover=coverMap[g.id];
  if(cover)hdr.style.backgroundImage=`url(${cover})`;else hdr.style.backgroundImage='';
  document.getElementById('modalBody').innerHTML=buildModal(g);
  document.getElementById('modalOverlay').classList.add('active');document.body.style.overflow='hidden';
}
function closeModal(){document.getElementById('modalOverlay').classList.remove('active');document.body.style.overflow=''}
function closeModalOutside(e){if(e.target===document.getElementById('modalOverlay'))closeModal()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});

function buildModal(g){
  let h=`<div class="meta-info"><span class="meta-item">📅 <strong>${g.year}年</strong></span><span class="meta-item">🏢 <strong>${g.developer}</strong></span><span class="meta-item">💻 <strong>${g.platforms.join(' / ')}</strong></span><span class="meta-item">🖼️ <strong>CG ${g.cgCount}+</strong></span></div>`;
  if(g.tags)h+=`<div class="meta-info">${g.tags.map(t=>`<span class="meta-item" style="background:rgba(126,200,227,0.08);border-color:rgba(126,200,227,0.15)">🏷️ ${t}</span>`).join('')}</div>`;
  h+=`<section><h3>📖 背景</h3><p style="white-space:pre-line;line-height:1.8;font-size:0.9rem;">${g.background}</p></section>`;
  h+='<section><h3>👥 角色</h3><div class="char-grid">';
  g.characters.forEach(c=>{h+=`<div class="char-card"><div class="char-avatar">🎭</div><div class="char-info"><h4>${c.name}</h4><p class="cv">🎙️ ${c.cv}</p><p>${c.desc}</p></div></div>`});
  h+='</div></section>';
  const cover=coverMap[g.id];
  h+=`<section><h3>🖼️ CG (共${g.cgCount}张)</h3><div class="cg-gallery">`;
  if(cover)h+=`<div class="cg-item"><img src="${cover}" alt="封面" loading="lazy"></div>`;
  for(let i=0;i<Math.min(4,g.cgCount);i++)h+=`<div class="cg-item"><div style="width:100%;height:100%;background:linear-gradient(135deg,rgba(196,113,245,0.15),rgba(126,200,227,0.15));display:flex;align-items:center;justify-content:center;font-size:2rem">🎨</div></div>`;
  h+='</div><p style="font-size:0.75rem;color:rgba(200,180,220,0.4);margin-top:6px">完整CG请访问 2DFan / VNDB / 月幕Galgame</p></section>';
  h+='<section><h3>🔗 资源</h3><div class="resource-links">';
  const m={official:'res-official',steam:'res-steam',vndb:'res-vndb',store:'res-store',resource:'res-resource'};
  g.resources.forEach(r=>{h+=`<a href="${r.url}" target="_blank" class="resource-link ${m[r.type]||'res-store'}">${r.label}</a>`});
  h+='</div><p style="margin-top:10px;font-size:0.78rem;color:rgba(255,211,0,0.6)">💡 正版首选 Steam/官网。中文资源参考 2DFan/青桔网/Hikarinagi/NekoGAL/稻荷GAL/Singureo</p></section>';
  return h;
}

init();
</script>
</body>
</html>
