{"code": "
import json, urllib.request, time

# Retry failed searches with different terms
retries = {
    "ginka": "GINKA 紺野",
    "fate_sr": "Fate Samurai Remnant 江戸",
    "hbr": "Heaven Burns Red 麻枝",
    "summer_pockets": "Summer Pockets Key",
    "summer_pockets_rb": "Summer Pockets Reflection",
}

results = {}
for fname, term in retries.items():
    try:
        data = json.dumps({
            "filters": ["search", "=", term],
            "fields": "id,title,image.url,image.id",
            "results": 5
        }).encode()
        req = urllib.request.Request("https://api.vndb.org/kana/vn", data=data, headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=15) as resp:
            r = json.loads(resp.read())
            results[fname] = [{"id": x["id"], "title": x["title"][:60], "cover": x.get("image",{}).get("url","")} for x in r.get("results",[])]
        time.sleep(0.4)
    except Exception as e:
        results[fname] = {"error": str(e)}

print(json.dumps(results, indent=2, ensure_ascii=False))
"}

{"content": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>🌸 Galgame 年鉴 2020-2025 · 阿罗娜的恋爱指南</title>
<style>
:root{--pink:#ff6b9d;--purple:#c471f5;--blue:#7ec8e3;--bg:rgba(8,6,20,0.94);--card:rgba(22,16,40,0.9);--text:#e8e0f8;--muted:rgba(190,170,210,0.55);--radius:14px}
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif;color:var(--text);line-height:1.6;min-height:100vh;overflow-x:hidden;background:#080614 fixed;position:relative}
body::before{content:'';position:fixed;inset:0;z-index:0;background:url('galgame_assets/bg/summer_pockets_bg.jpg') center/cover no-repeat;opacity:0.35;filter:blur(3px) brightness(0.5)}
body::after{content:'';position:fixed;inset:0;z-index:0;background:radial-gradient(ellipse at 25% 25%,rgba(255,107,157,0.06),transparent 50%),radial-gradient(ellipse at 75% 60%,rgba(126,200,227,0.06),transparent 50%)}
.petal-container{position:fixed;inset:0;pointer-events:none;z-index:9999}
.petal{position:absolute;top:-5%;font-size:1.1rem;animation:fall linear forwards;pointer-events:none;opacity:0.5}
@keyframes fall{0%{transform:translateY(0)rotate(0)translateX(0);opacity:0.7}100%{transform:translateY(110vh)rotate(720deg)translateX(-50px);opacity:0}}
.mini-murasame{position:fixed;pointer-events:none;z-index:10002;animation:muraPop 1.5s ease-out forwards;text-align:center}
.mini-murasame .m-body{font-size:44px;line-height:1;filter:drop-shadow(0 3px 6px rgba(255,170,80,0.5))}
.mini-murasame .m-text{font-size:11px;color:#ffe0c0;margin-top:2px;text-shadow:0 0 8px rgba(255,170,80,0.6)}
@keyframes muraPop{0%{transform:translateY(0)scale(0)rotate(-40deg);opacity:1}20%{transform:translateY(-40px)scale(1.3)rotate(5deg)}100%{transform:translateY(-100px)scale(0.2)rotate(25deg);opacity:0}}

/* Header - 青桔风简洁 */
header{position:sticky;top:0;z-index:100;background:rgba(12,8,28,0.92);backdrop-filter:blur(20px);padding:18px 24px;display:flex;align-items:center;justify-content:center;gap:12px;border-bottom:1px solid rgba(255,107,157,0.12);box-shadow:0 2px 20px rgba(0,0,0,0.3);flex-wrap:wrap}
header .logo{font-size:1.6rem;font-weight:900;background:linear-gradient(135deg,#ff6b9d,#c471f5,#7ec8e3);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
header .nav-links{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
