.music-bar{position:fixed;bottom:0;left:0;right:0;z-index:300;background:rgba(12,6,24,0.95);backdrop-filter:blur(12px);border-top:1px solid rgba(255,107,157,0.1);padding:8px 16px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:center}
