.music-bar .m-dots{display:flex;gap:5px}
.music-bar .m-dot{width:7px;height:7px;border-radius:50%;background:rgba(255,255,255,0.2);cursor:pointer;transition:all 0.3s}
.music-bar .m-dot.active{background:var(--pink);box-shadow:0 0 8px rgba(255,107,157,0.5)}
.m-btn{width:32px;height:32px;border-radius:50%;border:1px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.03);color:#c8b8e0;cursor:pointer;font-size:0.8rem;display:flex;align-items:center;justify-content:center;transition:all 0.3s;flex-shrink:0}
