// ===== INIT =====
function init(){
  const ys=[...new Set(games.map(g=>g.year))].sort(),ds=[...new Set(games.map(g=>g.developer))].sort();
  const selY=document.getElementById('filterYear'),selD=document.getElementById('filterDev');
  ys.forEach(y=>{const o=document.createElement('option');o.value=y;o.textContent=y;selY.appendChild(o)});
  ds.forEach(d=>{const o=document.createElement('option');o.value=d;o.textContent=d;selD.appendChild(o)});
  renderGames(games);
}
function renderGames(list){
  const gd=document.getElementById('gamesGrid'),nr=document.getElementById('noResults'),cnt=document.getElementById('gameCount');
  gd.innerHTML='';cnt.textContent=list.length;
  if(!list.length){gd.style.display='none';nr.style.display='block';return}
  gd.style.display='grid';nr.style.display='none';
  list.forEach(g=>{
    const c=document.createElement('div');c.className='game-card';c.onclick=()=>openModal(g);
    c.innerHTML=`<div class="game-card-image"><img src="${cm[g.id]||''}" alt="${g.title}" loading="lazy" onerror="this.style.display='none';this.parentElement.style.background='linear-gradient(135deg,rgba(255,107,157,0.2),rgba(126,200,227,0.2))'"><span class="year-badge">${g.year}</span></div><div class="game-card-body"><h3>${g.title}</h3><p class="title-jp">${g.titleJp}</p><div class="meta"><span class="tag tag-dev">${g.developer}</span>${g.platforms.map(p=>`<span class="tag tag-plat">${p}</span>`).join('')}</div><p class="desc">${g.desc}</p></div>`;
    gd.appendChild(c);
  });
}
function filterTag(t){if(t==='2024'){document.getElementById('filterYear').value='2024';applyFilters()}else{renderGames(games.filter(g=>g.developer.includes(t)||(g.tags||[]).includes(t)))}};

// ===== FILTERS =====
function applyFilters(){
  const s=document.getElementById('searchInput').value.toLowerCase().trim();
  const y=document.getElementById('filterYear').value,p=document.getElementById('filterPlatform').value,d=document.getElementById('filterDev').value;
  let f=games;
  if(s)f=f.filter(g=>g.title.toLowerCase().includes(s)||g.titleJp.includes(s)||g.developer.toLowerCase().includes(s)||g.desc.toLowerCase().includes(s)||g.characters.some(c=>c.n.includes(s)||c.cv.includes(s))||(g.tags||[]).some(t=>t.includes(s)));
  if(y)f=f.filter(g=>g.year===parseInt(y));if(p)f=f.filter(g=>g.platforms.includes(p));if(d)f=f.filter(g=>g.developer===d);
  renderGames(f);updateAC(s);
}
function resetFilters(){
  document.getElementById('searchInput').value='';['filterYear','filterPlatform','filterDev'].forEach(id=>document.getElementById(id).value='');
  document.getElementById('autocompleteDropdown').classList.remove('active');renderGames(games);
}
let acSel=-1;
function updateAC(q){
  const dd=document.getElementById('autocompleteDropdown');
  if(!q||q.length<1){dd.classList.remove('active');acSel=-1;return}
  const sug=[];games.forEach(g=>{if(g.title.toLowerCase().includes(q))sug.push({t:'🎮',v:g.title});if(g.developer.toLowerCase().includes(q))sug.push({t:'🏢',v:g.developer});g.characters.forEach(c=>{if(c.n.includes(q))sug.push({t:'👤',v:c.n})})});
  const un=[...new Map(sug.map(s=>[s.t+s.v,s])).values()].slice(0,8);
  if(!un.length){dd.classList.remove('active');return}
  dd.innerHTML=un.map((s,i)=>`<div class="autocomplete-item${i===acSel?' selected':''}" data-idx="${i}">${s.t} ${s.v}</div>`).join('');
  dd.classList.add('active');
  dd.querySelectorAll('.autocomplete-item').forEach(el=>el.onclick=function(){document.getElementById('searchInput').value=this.textContent.replace(/^.\s*/,'');dd.classList.remove('active');applyFilters()});
}
document.getElementById('searchInput').addEventListener('input',e=>{acSel=-1;applyFilters()});
document.getElementById('searchInput').addEventListener('keydown',e=>{
  const dd=document.getElementById('autocompleteDropdown'),its=dd.querySelectorAll('.autocomplete-item');
  if(e.key==='ArrowDown'){e.preventDefault();acSel=Math.min(acSel+1,its.length-1);its.forEach((el,i)=>el.classList.toggle('selected',i===acSel))}
  else if(e.key==='ArrowUp'){e.preventDefault();acSel=Math.max(acSel-1,-1);its.forEach((el,i)=>el.classList.toggle('selected',i===acSel))}
  else if(e.key==='Enter'&&acSel>=0){e.preventDefault();its[acSel].click()}
  else if(e.key==='Escape'){dd.classList.remove('active')}
});
document.addEventListener('click',e=>{if(!e.target.closest('.search-input-wrap'))document.getElementById('autocompleteDropdown').classList.remove('active')});
['filterYear','filterPlatform','filterDev'].forEach(id=>document.getElementById(id).addEventListener('change',applyFilters));

// ===== MODAL =====
function openModal(g){
  document.getElementById('modalTitle').textContent=g.title;
  document.getElementById('modalTitleJp').textContent=g.titleJp;
  const hdr=document.querySelector('.modal-header'),cv=cm[g.id];
  if(cv)hdr.style.backgroundImage=`url(${cv})`;else hdr.style.backgroundImage='';
  document.getElementById('modalBody').innerHTML=(function(){
    let h=`<div class="meta-info"><span class="meta-item">📅 <strong>${g.year}年</strong></span><span class="meta-item">🏢 <strong>${g.developer}</strong></span><span class="meta-item">💻 <strong>${g.platforms.join(' / ')}</strong></span><span class="meta-item">🖼️ <strong>${g.cgCount}+ CG</strong></span></div>`;
    if(g.tags)h+=`<div class="meta-info">${g.tags.map(t=>`<span class="meta-item" style="background:rgba(126,200,227,0.06);border-color:rgba(126,200,227,0.1)">🏷️ ${t}</span>`).join('')}</div>`;
    h+=`<section><h3>📖 背景说明</h3><p style="white-space:pre-line;line-height:1.8;font-size:0.88rem">${g.background}</p></section>`;
    h+='<section><h3>👥 人物简介</h3><div class="char-grid">';
    g.characters.forEach(c=>{h+=`<div class="char-card"><div class="char-avatar">🎭</div><div class="char-info"><h4>${c.n}</h4><p class="cv">🎙️ ${c.cv}</p><p>${c.d}</p></div></div>`});
    h+='</div></section>';
    h+=`<section><h3>🖼️ CG预览 (共${g.cgCount}张)</h3><div class="cg-gallery">`;
    if(cv)h+=`<div class="cg-item"><img src="${cv}" loading="lazy"></div>`;
    for(let i=0;i<Math.min(4,g.cgCount);i++)h+=`<div class="cg-item"><div style="width:100%;height:100%;background:linear-gradient(135deg,rgba(196,113,245,0.12),rgba(126,200,227,0.12));display:flex;align-items:center;justify-content:center;font-size:2rem">🎨</div></div>`;
    h+=`</div><p style="font-size:0.73rem;color:var(--muted);margin-top:6px">💡 完整CG请访问 <b>2DFan</b> / <b>VNDB</b> / <b>月幕Galgame</b></p></section>`;
    h+='<section><h3>🔗 资源途径</h3><div class="resource-links">';
    const m={official:'res-official',steam:'res-steam',vndb:'res-vndb',store:'res-store',resource:'res-resource'};
    g.resources.forEach(r=>{h+=`<a href="${r.u}" target="_blank" class="resource-link ${m[r.t]||'res-store'}">${r.l}</a>`});
    h+='</div><p style="margin-top:8px;font-size:0.76rem;color:rgba(255,211,0,0.55)">💡 正版首选 Steam/官网 · 中文资源参考 2DFan/青桔网/Hikarinagi/NekoGAL/稻荷GAL/Singureo</p></section>';
    return h;
  })();
  document.getElementById('modalOverlay').classList.add('active');document.body.style.overflow='hidden';
}
function closeModal(){document.getElementById('modalOverlay').classList.remove('active');document.body.style.overflow=''}
function closeModalOutside(e){if(e.target===document.getElementById('modalOverlay'))closeModal()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});

init();
</script>
</body>
</html>
