import json, urllib.request, time

# Search VNDB for games that have screenshots
games_with_screenshots = [
    ("ATRI", "ATRI -My Dear Moments-"),
    ("Summer Pockets", "Summer Pockets"),
    ("Senren Banka", "Senren Banka"),
    ("Aokana", "Ao no Kanata no Four Rhythm"),
    ("Sakura no Uta", "Sakura no Uta -Sakura no Mori-"),
    ("Riddle Joker", "RIDDLE JOKER"),
    ("Sanoba Witch", "Sanoba Witch"),
    ("Clover Days", "Clover Day's"),
    ("Kinkoi", "Kinkoi Loveriche"),
]

results = {}
for name, term in games_with_screenshots:
    try:
        data = json.dumps({
            "filters": ["search", "=", term],
            "fields": "id,title,image.url,screenshots.url",
            "results": 1
        }).encode()
        req = urllib.request.Request("https://api.vndb.org/kana/vn", data=data, headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=15) as resp:
            r = json.loads(resp.read())
            if r["results"]:
                vn = r["results"][0]
                screenshots = vn.get("screenshots", [])
                results[name] = {
                    "title": vn["title"],
                    "num_screenshots": len(screenshots),
                    "screenshots": [s.get("url","") for s in screenshots[:5]]
                }
        time.sleep(0.3)
    except Exception as e:
        results[name] = {"error": str(e)}

print(json.dumps(results, indent=2, ensure_ascii=False))
"}

