@keyframes mPop{0%{transform:translateY(0)scale(0)rotate(-35deg)}20%{transform:translateY(-38px)scale(1.3)rotate(5deg)}100%{transform:translateY(-90px)scale(0.2)rotate(20deg);opacity:0}}

header{position:sticky;top:0;z-index:100;background:rgba(12,6,26,0.94);backdrop-filter:blur(16px);padding:20px;text-align:center;border-bottom:1px solid rgba(255,107,157,0.12);box-shadow:0 2px 24px rgba(0,0,0,0.3)}
