.mbtn{width:32px;height:32px;border-radius:50%;border:1px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.03);color:#c8b8e0;cursor:pointer;font-size:0.8rem;display:flex;align-items:center;justify-content:center;transition:all 0.3s;flex-shrink:0}
.mbtn:hover{background:rgba(196,113,245,0.15);border-color:var(--purple)}
.mbtn.play{width:38px;height:38px;background:linear-gradient(135deg,#ff6b9d,#c471f5);border:none;color:#fff;font-size:1rem}
.mbtn.play.on{animation:mp 2s infinite}
