// ===== INIT =====
function init(){
  const ys=[...new Set(games.map(g=>g.year))].sort(),ds=[...new Set(games.map(g=>g.developer))].sort();
  ys.forEach(y=>{const o=document.createElement('option');o.value=y;o.textContent=y;document.getElementById('filterYear').appendChild(o)});
  ds.forEach(d=>{const o=document.createElement('option');o.value=d;o.textContent=d;document.getElementById('filterDev').appendChild(o)});
  renderGames(games);renderRSites();
}
function renderGames(list){
  const gd=document.getElementById('gamesGrid'),nr=document.getElementById('noResults'),cnt=document.getElementById('gameCount');
  gd.innerHTML='';cnt.textContent=list.length;
  if(!list.length){gd.style.display='none';nr.style.display='block';return}
  gd.style.display='grid';nr.style.display='none';
  list.forEach(g=>{
    const c=document.createElement('div');c.className='game-card';c.onclick=()=>openModal(g);
    c.innerHTML=`<div class="gci"><img src="${cm[g.id]||''}" alt="${g.title}" loading="lazy" onerror="this.style.display='none';this.parentElement.style.background='linear-gradient(135deg,rgba(255,107,157,0.2),rgba(126,200,227,0.2))'"><span class="yb">${g.year}</span></div><div class="gcb"><h3>${g.title}</h3><p class="tj">${g.titleJp}</p><div class="meta"><span class="tag td">${g.developer}</span>${g.platforms.map(p=>`<span class="tag tp">${p}</span>`).join('')}</div><p class="desc">${g.desc}</p></div>`;
    gd.appendChild(c);
  });
}

// ===== FILTERS =====
function applyFilters(){
  const s=document.getElementById('searchInput').value.toLowerCase().trim();
  const y=document.getElementById('filterYear').value,p=document.getElementById('filterPlatform').value,d=document.getElementById('filterDev').value;
  let f=games;
  if(s)f=f.filter(g=>g.title.toLowerCase().includes(s)||g.titleJp.includes(s)||g.developer.toLowerCase().includes(s)||g.desc.includes(s)||g.characters.some(c=>c.n.includes(s)||c.cv.includes(s))||(g.tags||[]).some(t=>t.includes(s)));
  if(y)f=f.filter(g=>g.year===parseInt(y));if(p)f=f.filter(g=>g.platforms.includes(p));if(d)f=f.filter(g=>g.developer===d);
  renderGames(f);updateAC(s);
}
function resetFilters(){
  document.getElementById('searchInput').value='';['filterYear','filterPlatform','filterDev'].forEach(id=>document.getElementById(id).value='');
  document.getElementById('acDropdown').classList.remove('on');renderGames(games);
}
let acS=-1;
function updateAC(q){
  const dd=document.getElementById('acDropdown');
  if(!q||q.length<1){dd.classList.remove('on');acS=-1;return}
  const sug=[];games.forEach(g=>{if(g.title.toLowerCase().includes(q))sug.push({t:'游戏',v:g.title});if(g.developer.toLowerCase().includes(q))sug.push({t:'开发商',v:g.developer});g.characters.forEach(c=>{if(c.n.includes(q))sug.push({t:'角色',v:c.n})})});
  const un=[...new Map(sug.map(s=>[s.t+s.v,s])).values()].slice(0,6);
  if(!un.length){dd.classList.remove('on');return}
  dd.innerHTML=un.map((s,i)=>`<div class="ac-i${i===acS?' sel':''}" data-idx="${i}"><b>${s.t}</b> ${s.v}</div>`).join('');
  dd.classList.add('on');
  dd.querySelectorAll('.ac-i').forEach(el=>el.onclick=function(){document.getElementById('searchInput').value=this.textContent.replace(/^[^ ]+ /,'');dd.classList.remove('on');applyFilters()});
}
document.getElementById('searchInput').addEventListener('input',e=>{acS=-1;applyFilters()});
document.getElementById('searchInput').addEventListener('keydown',e=>{
  const dd=document.getElementById('acDropdown'),its=dd.querySelectorAll('.ac-i');
  if(e.key==='ArrowDown'){e.preventDefault();acS=Math.min(acS+1,its.length-1);its.forEach((el,i)=>el.classList.toggle('sel',i===acS))}
  else if(e.key==='ArrowUp'){e.preventDefault();acS=Math.max(acS-1,-1);its.forEach((el,i)=>el.classList.toggle('sel',i===acS))}
  else if(e.key==='Enter'&&acS>=0){e.preventDefault();its[acS].click()}
  else if(e.key==='Escape'){dd.classList.remove('on')}
});
document.addEventListener('click',e=>{if(!e.target.closest('.s-wrap'))document.getElementById('acDropdown').classList.remove('on')});
['filterYear','filterPlatform','filterDev'].forEach(id=>document.getElementById(id).addEventListener('change',applyFilters));

// ===== MODAL =====
function openModal(g){
  document.getElementById('modalTitle').textContent=g.title;
  document.getElementById('modalTitleJp').textContent=g.titleJp;
  const hdr=document.querySelector('.mh'),cv=cm[g.id];
  if(cv)hdr.style.backgroundImage=`url(${cv})`;else hdr.style.backgroundImage='';
  document.getElementById('modalBody').innerHTML=(function(){
    let h=`<div class="mi"><span class="mi-item">📅 <strong>${g.year}年</strong></span><span class="mi-item">🏢 <strong>${g.developer}</strong></span><span class="mi-item">💻 <strong>${g.platforms.join(' / ')}</strong></span><span class="mi-item">🖼️ <strong>${g.cgCount}+ CG</strong></span></div>`;
    if(g.tags)h+=`<div class="mi">${g.tags.map(t=>`<span class="mi-item" style="background:rgba(126,200,227,0.06)">🏷️ ${t}</span>`).join('')}</div>`;
    h+=`<section><h3>📖 背景说明</h3><p style="white-space:pre-line;line-height:1.8;font-size:0.88rem">${g.background}</p></section>`;
    h+='<section><h3>👥 人物简介</h3><div class="ch">';
    g.characters.forEach(c=>{h+=`<div class="ch-card"><div class="ch-av">🎭</div><div class="ch-info"><h4>${c.n}</h4><p class="cv">🎙️ ${c.cv}</p><p>${c.d}</p></div></div>`});
    h+='</div></section>';
    // CG Gallery
    h+=`<section><h3>🖼️ CG预览 (共${g.cgCount}张)</h3><div class="cg">`;
    // Show cover as first CG
    if(cv)h+=`<div class="cg-i"><img src="${cv}" loading="lazy"></div>`;
    // Show CG screenshots if available
    // Summer Pockets CGs
    if(g.id===19||g.id===32){
      h+=`<div class="cg-i"><img src="${CG}sp_cg1.jpg" loading="lazy" onerror="this.parentElement.innerHTML='<div class=ph>🎨</div>'"></div>`;
      h+=`<div class="cg-i"><img src="${CG}sp_cg2.jpg" loading="lazy" onerror="this.parentElement.innerHTML='<div class=ph>🎨</div>'"></div>`;
    }
    // Placeholder CGs for remaining
    const remaining=Math.max(0,(g.id===19||g.id===32?3:5));
    for(let i=0;i<remaining;i++)h+=`<div class="cg-i"><div class="ph">🎨</div></div>`;
    h+=`</div><p style="font-size:0.74rem;color:var(--muted);margin-top:6px">💡 完整CG请访问 <b>2DFan</b> / <b>VNDB</b> / <b>月幕Galgame</b> 查看</p></section>`;
    // Resources
    h+='<section><h3>🔗 资源获取途径</h3><div class="rl">';
    const m={official:'ro',steam:'rs',vndb:'rv',store:'rst',resource:'rlink rst'};
    g.resources.forEach(r=>{h+=`<a href="${r.u}" target="_blank" class="rlink ${m[r.t]||'rst'}">${r.l}</a>`});
    h+=`</div><p style="margin-top:8px;font-size:0.76rem;color:rgba(255,211,0,0.55)">💡 正版首选 Steam/官网 · 中文资源参考 2DFan/青桔网/Hikarinagi/NekoGAL/稻荷GAL/Singureo</p></section>`;
    return h;
  })();
  document.getElementById('modalOverlay').classList.add('on');document.body.style.overflow='hidden';
}
function closeModal(){document.getElementById('modalOverlay').classList.remove('on');document.body.style.overflow=''}
function closeModalOutside(e){if(e.target===document.getElementById('modalOverlay'))closeModal()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});

init();
</script>
</body>
</html>
