const musicFiles=[
  '雪桜草 - 願い.mp3',
  'Mix-.mp3',
  '花.mp3',
  'キミの花.mp3',
  'ver).mp3',
  'Feel.mp3',
  '斜陽.mp3',
  'Love.mp3'
];
let audio=new Audio(),playing=false,curIdx=-1;
let loopMode=2; // 0=off, 1=single, 2=all
let shuffleOn=false;
let playlist=[...musicFiles];
audio.volume=0.5;

function getPath(f){return 'galgame_assets/music/'+f}
function loadIdx(i){
  if(i<0||i>=playlist.length)return;
  curIdx=i;audio.src=getPath(playlist[i]);
  document.getElementById('mTitle').textContent='🎵 '+playlist[i].replace('.mp3','');
  document.querySelectorAll('.mdot').forEach((d,j)=>d.classList.toggle('on',j===i));
}
function togglePlay(){
  if(curIdx<0)loadIdx(0);
  if(!playing){audio.play().catch(e=>{});playing=true}else{audio.pause();playing=false}
  updateUI();
}
function updateUI(){
  document.getElementById('mPlay').classList.toggle('on',playing);
  document.getElementById('mPlay').textContent=playing?'⏸':'▶';
  document.getElementById('mLoop').textContent=['🔁','🔂','➡️'][loopMode];
  document.getElementById('mShuffle').style.color=shuffleOn?'#ff6b9d':'#c8b8e0';
}
function nextTrack(){
  if(shuffleOn){curIdx=Math.floor(Math.random()*playlist.length)}
  else{curIdx=(curIdx+1)%playlist.length}
  loadIdx(curIdx);if(playing){audio.play().catch(e=>{})}
}
function prevTrack(){
  if(shuffleOn){curIdx=Math.floor(Math.random()*playlist.length)}
  else{curIdx=(curIdx-1+playlist.length)%playlist.length}
  loadIdx(curIdx);if(playing){audio.play().catch(e=>{})}
}
function toggleLoop(){
  loopMode=(loopMode+1)%3;updateUI();
}
function toggleShuffle(){
  shuffleOn=!shuffleOn;updateUI();
  // Rebuild playlist
  if(!shuffleOn)playlist=[...musicFiles];
}
function gamePlay(){
  // Play first track
  stopAll();loadIdx(0);playing=true;audio.play().catch(e=>{});updateUI();
}
function stopAll(){audio.pause();playing=false;updateUI()}
audio.addEventListener('ended',()=>{
  if(loopMode===1){audio.currentTime=0;audio.play().catch(e=>{})}
  else if(loopMode===2){nextTrack()}
  else{playing=false;updateUI()}
});
// Init playlist dots
const md=document.getElementById('mDots');md.innerHTML='';
musicFiles.forEach((f,i)=>{
  const d=document.createElement('div');d.className='mdot';
  d.onclick=()=>{loadIdx(i);if(!playing)togglePlay();else{audio.play().catch(e=>{})}};
  md.appendChild(d);
