{"content": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>🌸 Galgame 年鉴 · 阿罗娜的恋爱指南</title>
<style id="themeStyle">
/* ===== DEFAULT: Dark Sakura Theme ===== */
:root{--pink:#ff6b9d;--purple:#c471f5;--blue:#7ec8e3;--text:#e8e0f8;--muted:rgba(210,195,235,0.6);--r:14px;
  --header-bg:rgba(8,4,18,0.8);--card-bg:rgba(18,10,35,0.65);--search-bg:rgba(18,10,35,0.6);
  --input-bg:rgba(10,5,22,0.5);--btn-rst:rgba(255,255,255,0.04);--btn-rst-bd:rgba(255,255,255,0.06);
  --card-bd:rgba(255,107,157,0.07);--modal-bg:rgba(14,8,26,0.94);--modal-hdr:rgba(14,8,26,0.84);
  --music-bg:rgba(8,4,18,0.88);--footer-color:rgba(210,195,235,0.4);--rs-card-bg:rgba(18,10,35,0.5);
  --ch-card-bg:rgba(20,10,35,0.4);
}
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:'Segoe UI','PingFang SC','Microsoft YaHei',sans-serif;color:var(--text);line-height:1.6;min-height:100vh;overflow-x:hidden;position:relative}
body::before{content:'';position:fixed;inset:0;z-index:0;background:url('galgame_assets/bg/summer_pockets_bg.jpg') center/cover no-repeat fixed;opacity:0.4;filter:brightness(0.35) saturate(0.8)}
body::after{content:'';position:fixed;inset:0;z-index:0;background:linear-gradient(180deg,rgba(4,2,12,0.7) 0%,rgba(8,4,20,0.55) 50%,rgba(4,2,12,0.8) 100%)}

/* Stars */
.stars{position:fixed;inset:0;pointer-events:none;z-index:0}
.star{position:absolute;background:#fff;border-radius:50%;animation:twinkle var(--d) infinite;animation-delay:var(--dl)}
@keyframes twinkle{0%,100%{opacity:0.2;transform:scale(1)}50%{opacity:0.9;transform:scale(1.8)}}

/* Petals */
.petals{position:fixed;inset:0;pointer-events:none;z-index:9999}
.petal{position:absolute;top:-8%;animation:fall linear forwards;pointer-events:none;opacity:0.45}
@keyframes fall{0%{transform:translateY(0)rotate(0)translateX(0);opacity:0.6}100%{transform:translateY(112vh)rotate(720deg)translateX(-60px);opacity:0}}

/* Mini Murasame */
.mini-mura{position:fixed;pointer-events:none;z-index:10002;animation:mPop 1.5s ease-out forwards;text-align:center}
.mini-mura .mb{font-size:42px;filter:drop-shadow(0 3px 6px rgba(255,170,80,0.5))}
.mini-mura .mt{font-size:10px;color:#ffe0c0;text-shadow:0 0 6px rgba(255,170,80,0.5)}
@keyframes mPop{0%{transform:translateY(0)scale(0)rotate(-35deg)}20%{transform:translateY(-38px)scale(1.3)rotate(5deg)}100%{transform:translateY(-90px)scale(0.2)rotate(20deg);opacity:0}}

header{position:sticky;top:0;z-index:100;background:var(--header-bg);backdrop-filter:blur(20px);padding:16px 20px;text-align:center;border-bottom:1px solid rgba(255,107,157,0.1);box-shadow:0 1px 20px rgba(0,0,0,0.2);display:flex;align-items:center;justify-content:center;gap:16px;flex-wrap:wrap}
header h1{background:linear-gradient(135deg,#ff6b9d,#c471f5,#7ec8e3);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;font-size:1.7rem;font-weight:900;letter-spacing:2px}
header .sub{color:rgba(210,195,235,0.65);font-size:0.8rem}
.hc{display:inline-block;animation:hb 2s infinite;font-size:1.3rem}
@keyframes hb{0%,100%{transform:translateY(0)}30%{transform:translateY(-7px)rotate(5deg)}60%{transform:translateY(0)rotate(-3deg)}}
.theme-btn{width:34px;height:34px;border-radius:50%;border:1px solid rgba(255,255,255,0.12);background:rgba(255,255,255,0.05);color:#c8b8e0;cursor:pointer;font-size:0.9rem;transition:all 0.3s;flex-shrink:0}
.theme-btn:hover{background:rgba(196,113,245,0.2);border-color:var(--purple)}

.container{max-width:1360px;margin:0 auto;padding:0 20px;position:relative;z-index:1}

.search-box{background:var(--search-bg);backdrop-filter:blur(14px);border:1px solid rgba(255,107,157,0.1);border-radius:var(--r);padding:18px;margin:18px auto 22px;max-width:1360px;box-shadow:0 3px 18px rgba(0,0,0,0.15)}
.s-row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}
.s-wrap{flex:1;min-width:170px;position:relative}
.s-in{width:100%;padding:10px 14px;border:1.5px solid rgba(255,107,157,0.15);border-radius:24px;font-size:0.88rem;outline:none;background:var(--input-bg);color:var(--text);transition:all 0.3s}
.s-in:focus{border-color:var(--pink);box-shadow:0 0 12px rgba(255,107,157,0.08)}
.s-in::placeholder{color:rgba(190,170,210,0.35)}
.ac-dd{display:none;position:absolute;top:100%;left:0;right:0;background:rgba(14,8,28,0.97);border:1px solid rgba(255,107,157,0.18);border-radius:0 0 12px 12px;max-height:180px;overflow-y:auto;z-index:60;margin-top:2px}
.ac-dd.on{display:block}
.ac-i{padding:8px 14px;cursor:pointer;font-size:0.78rem;border-bottom:1px solid rgba(255,255,255,0.02);transition:background 0.2s}
.ac-i:hover,.ac-i.sel{background:rgba(255,107,157,0.12)}
.fs{padding:10px 12px;border:1.5px solid rgba(255,107,157,0.15);border-radius:24px;font-size:0.83rem;background:var(--input-bg);color:var(--text);cursor:pointer;outline:none;min-width:100px}
.fs:focus{border-color:var(--purple)}
.btn{padding:10px 18px;border:none;border-radius:24px;font-size:0.83rem;cursor:pointer;transition:all 0.3s;font-weight:700}
.btn-p{background:linear-gradient(135deg,#ff6b9d,#c471f5);color:#fff;box-shadow:0 3px 10px rgba(196,113,245,0.2)}
.btn-p:hover{transform:translateY(-2px);box-shadow:0 5px 18px rgba(196,113,245,0.35)}
.btn-r{background:var(--btn-rst);color:var(--muted);border:1px solid var(--btn-rst-bd)}
.btn-r:hover{border-color:var(--purple);color:#d4c4f0}
.rc{margin-top:8px;font-size:0.78rem;color:var(--muted)}
.rc span{color:var(--pink);font-weight:700}

/* Game Grid */
.games-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:18px;padding-bottom:40px}
.game-card{background:var(--card-bg);backdrop-filter:blur(10px);border-radius:var(--r);overflow:hidden;cursor:pointer;transition:all 0.35s;border:1px solid var(--card-bd);position:relative}
.game-card::before{content:'';position:absolute;inset:-2px;border-radius:16px;background:linear-gradient(135deg,transparent,rgba(255,107,157,0.18),rgba(126,200,227,0.18),transparent);opacity:0;transition:opacity 0.35s;z-index:-1;filter:blur(4px)}
.game-card:hover::before{opacity:1}
.game-card:hover{transform:translateY(-5px);box-shadow:0 10px 28px rgba(196,113,245,0.15);border-color:rgba(255,107,157,0.22)}
.gci{height:200px;position:relative;overflow:hidden;background:#1a1030}
.gci img{width:100%;height:100%;object-fit:cover;transition:transform 0.5s}
.game-card:hover .gci img{transform:scale(1.05)}
.gci .yb{position:absolute;top:8px;right:8px;background:rgba(0,0,0,0.45);backdrop-filter:blur(4px);color:#fff;padding:3px 10px;border-radius:12px;font-size:0.7rem;font-weight:700;z-index:2}
.gcb{padding:14px}
.gcb h3{font-size:0.92rem;color:#f0e8ff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.gcb .tj{font-size:0.68rem;color:var(--muted);margin-bottom:6px}
.gcb .meta{display:flex;flex-wrap:wrap;gap:4px}
.tag{padding:2px 8px;border-radius:10px;font-size:0.64rem;font-weight:600}
.td{background:rgba(126,200,227,0.12);color:var(--blue)}
.tp{background:rgba(255,211,0,0.08);color:#ffd54f}

/* Modal */
.mo{display:none;position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:200;justify-content:center;align-items:flex-start;padding:20px;overflow-y:auto;backdrop-filter:blur(3px)}
.mo.on{display:flex}
.modal{background:var(--modal-bg);backdrop-filter:blur(16px);border-radius:var(--r);max-width:860px;width:100%;margin:16px 0;box-shadow:0 14px 40px rgba(0,0,0,0.4);animation:sU 0.3s ease;border:1px solid rgba(196,113,245,0.08)}
@keyframes sU{from{opacity:0;transform:translateY(30px)scale(0.97)}to{opacity:1;transform:translateY(0)scale(1)}}
.mh{padding:18px 22px;display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid rgba(255,107,157,0.08);position:relative;background-size:cover;background-position:center}
.mh::before{content:'';position:absolute;inset:0;background:var(--modal-hdr);border-radius:var(--r) var(--r) 0 0}
.mh>*{position:relative;z-index:1}
.mh h2{font-size:1.35rem;color:#f0e8ff}
.mh .tj{font-size:0.75rem;color:var(--muted)}
.mc{position:relative;z-index:2;background:none;border:1px solid rgba(255,255,255,0.08);font-size:1.3rem;cursor:pointer;color:rgba(210,195,235,0.4);padding:2px 10px;border-radius:50%}
.mc:hover{color:var(--pink);border-color:var(--pink)}
.mb{padding:18px 22px}
.mb section{margin-bottom:16px}
.mb section h3{font-size:1rem;background:linear-gradient(135deg,#ff6b9d,#c471f5);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;margin-bottom:8px;padding-bottom:4px;border-bottom:2px solid rgba(255,107,157,0.1)}
.mi{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}
.mi-item{padding:4px 12px;border-radius:14px;font-size:0.74rem;background:rgba(255,107,157,0.04);border:1px solid rgba(255,107,157,0.05)}
.mi-item strong{color:var(--pink)}
.ch{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px}
.ch-card{display:flex;gap:10px;background:var(--ch-card-bg);padding:10px;border-radius:8px;border:1px solid rgba(255,107,157,0.04);transition:all 0.2s}
.ch-card:hover{background:rgba(196,113,245,0.06)}
.ch-av{width:52px;height:52px;border-radius:50%;background:linear-gradient(135deg,#c471f5,#ff6b9d);display:flex;align-items:center;justify-content:center;font-size:1.3rem;flex-shrink:0}
.ch-info h4{font-size:0.83rem;color:#f0e8ff}
.ch-info .cv{font-size:0.66rem;color:var(--muted)}
.ch-info p{font-size:0.72rem;color:var(--muted);line-height:1.3}
.cg{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:8px}
.cg-i{border-radius:8px;overflow:hidden;border:1.5px solid rgba(126,200,227,0.08);aspect-ratio:16/10;transition:all 0.3s;cursor:pointer}
.cg-i img{width:100%;height:100%;object-fit:cover}
.cg-i:hover{transform:scale(1.04);border-color:rgba(196,113,245,0.35);box-shadow:0 3px 10px rgba(196,113,245,0.12)}
.cg-i .ph{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:2rem;background:linear-gradient(135deg,rgba(196,113,245,0.08),rgba(126,200,227,0.08))}
.rl{display:flex;flex-wrap:wrap;gap:6px}
.rlink{display:inline-flex;align-items:center;gap:3px;padding:7px 13px;border-radius:18px;text-decoration:none;font-size:0.78rem;font-weight:600;transition:all 0.3s}
.ro{background:linear-gradient(135deg,#ff6b9d,#f06292);color:#fff}
.ro:hover{transform:translateY(-2px);box-shadow:0 3px 10px rgba(255,107,157,0.25)}
.rv{background:rgba(126,200,227,0.12);color:var(--blue);border:1px solid rgba(126,200,227,0.12)}
.rv:hover{background:rgba(126,200,227,0.22)}
.rs{background:#1b2838;color:#fff}
.rs:hover{background:#2a475e}
.rst{background:rgba(255,211,0,0.08);color:#ffd54f;border:1px solid rgba(255,211,0,0.12)}
.rst:hover{background:rgba(255,211,0,0.15)}

/* Resource Sites */
.rs-title{text-align:center;margin:40px 0 18px;font-size:1.3rem;background:linear-gradient(135deg,#ff6b9d,#c471f5,#7ec8e3);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;font-weight:900}
.rs-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px;padding:0 20px 40px}
.rs-card{background:var(--rs-card-bg);backdrop-filter:blur(8px);border:1px solid rgba(196,113,245,0.1);border-radius:var(--r);padding:16px;transition:all 0.3s;text-decoration:none;color:var(--text);display:block;cursor:pointer}
.rs-card:hover{border-color:rgba(196,113,245,0.28);transform:translateY(-3px);box-shadow:0 5px 18px rgba(196,113,245,0.12)}
.rs-card .rsi{font-size:1.6rem;margin-bottom:4px}
.rs-card h4{font-size:0.9rem;color:#f0e8ff;margin-bottom:2px}
.rs-card .rsu{font-size:0.7rem;color:var(--muted);margin-bottom:4px}
.rs-card p{font-size:0.75rem;color:var(--muted);line-height:1.4}

/* Music */
.music-bar{position:fixed;bottom:0;left:0;right:0;z-index:300;background:var(--music-bg);backdrop-filter:blur(14px);border-top:1px solid rgba(255,107,157,0.08);padding:8px 14px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:center}
.music-bar .mtitle{font-size:0.76rem;color:var(--muted);max-width:240px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.music-bar .mdots{display:flex;gap:4px}
.music-bar .mdot{width:7px;height:7px;border-radius:50%;background:rgba(255,255,255,0.18);cursor:pointer;transition:all 0.3s}
.music-bar .mdot.on{background:var(--pink);box-shadow:0 0 8px rgba(255,107,157,0.5)}
.mbtn{width:30px;height:30px;border-radius:50%;border:1px solid rgba(255,255,255,0.08);background:rgba(255,255,255,0.03);color:#c8b8e0;cursor:pointer;font-size:0.75rem;display:flex;align-items:center;justify-content:center;transition:all 0.3s;flex-shrink:0}
.mbtn:hover{background:rgba(196,113,245,0.15);border-color:var(--purple)}
.mbtn.play{width:36px;height:36px;background:linear-gradient(135deg,#ff6b9d,#c471f5);border:none;color:#fff;font-size:0.95rem}
.mbtn.play.on{animation:mp 2s infinite}
